/* ----- CONFIGURACIÓN GENERAL ----- */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Arial, sans-serif;
}

/* ----- HEADER ----- */
.header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px 60px;
}

/* ----- LOGO ----- */
.logo {
    font-size: 18px;
    font-weight: bold;
}

.logo .tag {
    font-weight: normal;
}

/* ----- NAV ----- */
.nav {
    display: flex;
    gap: 40px;
}

/* Enlaces del menú: se igualan alturas */
.nav-link {
    text-decoration: none;
    color: black;
    font-size: 14px;
    letter-spacing: 1px;

    /* Ajuste clave para que todos tengan la MISMA altura */
    padding: 8px 10px;
}

/* ----- LINK ACTIVO (ABOUT) ----- */
.nav-link.active {
    background: black;
    color: white;
    border-radius: 8px;
    padding: 8px 18px; /* ancho mayor, pero misma altura */
}

/* ----- DIVISOR INFERIOR negro ----- */
.divider {
    width: 100%;
    height: 4px;
    background: black;
}

.title{
    width: 100%;
    height: auto;
    margin-top: 40px;
    text-align: center;
}

.subtitle{
    margin-top: 30px;
    text-align: center;
    position: relative;
    width: 100%;
    height: auto;
}

/* ----- FOOTER ----- */
.footer {
    background: white;
    padding: 60px 80px;
    border-top: 4px solid black;
}

.footer-container {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 60px;
}

/* COLUMNA IZQUIERDA */
.footer-brand h3 {
    font-size: 20px;
    margin-bottom: 30px;
}

.social-icons a {
    margin-right: 18px;
    font-size: 20px;
    color: #666;
    text-decoration: none;
}

.social-icons a:hover {
    color: #000;
}

/* COLUMNAS DERECHAS */
.footer-links {
    display: flex;
    gap: 80px;
}

.column h4 {
    font-size: 16px;
    margin-bottom: 15px;
}

.column a {
    display: block;
    text-decoration: none;
    color: #777;
    margin-bottom: 10px;
    font-size: 14px;
}

.column a:hover {
    color: black;
}

/* Responsivo */
@media (max-width: 900px) {
    .footer-container {
        flex-direction: column;
        gap: 40px;
    }

    .footer-links {
        flex-direction: column;
        gap: 40px;
    }
}

.img1{
    width: 500px;
    height: 400px;
    margin-top: 40px;
    display: block;
    margin-left: auto;
    margin-right: auto;
}

/* ----- CONFIGURACIÓN GENERAL ----- */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Arial, sans-serif;
}

/* ----- HEADER ----- */
.header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px 100px;
    position: relative;
}

/* ----- LOGO ----- */
.logo {
    font-size: 18px;
    font-weight: bold;
}

.logo .tag {
    font-weight: normal;
}

/* ----- NAV ----- */
.nav {
    display: flex;
    gap: 40px;
    transition: all 0.3s ease;
}

/* ----- MENÚ HAMBURGUESA ----- */
.hamburger {
    display: none;
    flex-direction: column;
    cursor: pointer;
    gap: 5px;
    z-index: 1001;
    background: none;
    border: none;
    padding: 5px;
}

.hamburger span {
    width: 25px;
    height: 3px;
    background: black;
    border-radius: 3px;
    transition: all 0.3s ease;
}

.hamburger.active span:nth-child(1) {
    transform: rotate(45deg) translate(8px, 8px);
}

.hamburger.active span:nth-child(2) {
    opacity: 0;
}

.hamburger.active span:nth-child(3) {
    transform: rotate(-45deg) translate(7px, -7px);
}

/* Enlaces del menú: se igualan alturas */
.nav-link {
    text-decoration: none;
    color: black;
    font-size: 14px;
    letter-spacing: 1px;

    /* Ajuste clave para que todos tengan la MISMA altura */
    padding: 8px 10px;
}

/* ----- LINK ACTIVO (ABOUT) ----- */
.nav-link.active {
    background: black;
    color: white;
    border-radius: 8px;
    padding: 8px 18px; /* ancho mayor, pero misma altura */
}

/* ----- DIVISOR INFERIOR negro ----- */
.divider {
    width: 100%;
    height: 4px;
    background: black;
}

.title{
    width: 100%;
    height: auto;
    margin-top: 40px;
    text-align: center;
}

.subtitle{
    margin-top: 30px;
    text-align: center;
    position: relative;
    width: 100%;
    height: auto;
}

/* ----- FOOTER ----- */
.footer {
    background: white;
    padding: 60px 80px;
    border-top: 4px solid black;
}

.footer-container {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 60px;
}

/* COLUMNA IZQUIERDA */
.footer-brand h3 {
    font-size: 20px;
    margin-bottom: 30px;
}

.social-icons a {
    margin-right: 18px;
    font-size: 20px;
    color: #666;
    text-decoration: none;
}

.social-icons a:hover {
    color: #000;
}

/* COLUMNAS DERECHAS */
.footer-links {
    display: flex;
    gap: 80px;
}

.column h4 {
    font-size: 16px;
    margin-bottom: 15px;
}

.column a {
    display: block;
    text-decoration: none;
    color: #777;
    margin-bottom: 10px;
    font-size: 14px;
}

.column a:hover {
    color: black;
}

/* ----- OVERLAY PARA MENÚ MÓVIL ----- */
.overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100vh;
    background: rgba(0, 0, 0, 0.5);
    z-index: 999;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.overlay.active {
    display: block;
    opacity: 1;
}

/* ----- RESPONSIVIDAD HEADER ----- */
@media (max-width: 900px) {
    .header {
        padding: 20px 60px;
    }

    .hamburger {
        display: flex;
    }

    .nav {
        position: fixed;
        top: 0;
        right: -100%;
        width: 70%;
        max-width: 350px;
        height: 100vh;
        background: white;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        gap: 30px;
        box-shadow: -5px 0 15px rgba(0, 0, 0, 0.2);
        transition: right 0.4s ease;
        z-index: 1000;
    }

    .nav.active {
        right: 0;
    }

    .nav-link {
        font-size: 16px;
        padding: 10px 20px;
    }

    .nav-link.active {
        padding: 10px 25px;
    }
}

@media (max-width: 600px) {
    .header {
        padding: 20px 30px;
    }

    .nav {
        width: 85%;
    }
}

/* Responsivo Footer */
@media (max-width: 900px) {
    .footer-container {
        flex-direction: column;
        gap: 40px;
    }

    .footer-links {
        flex-direction: column;
        gap: 40px;
    }
}

.img1{
    width: 500px;
    height: 400px;
    margin-top: 40px;
    display: block;
    margin-left: auto;
    margin-right: auto;
}

// Funcionalidad del menú hamburguesa

const hamburger = document.querySelector('.hamburger');
const nav = document.querySelector('.nav');
const overlay = document.querySelector('.overlay');
const navLinks = document.querySelectorAll('.nav-link');

// Toggle del menú al hacer clic en hamburguesa
hamburger.addEventListener('click', () => {
    hamburger.classList.toggle('active');
    nav.classList.toggle('active');
    overlay.classList.toggle('active');

    // Prevenir scroll del body cuando el menú está abierto
    document.body.style.overflow = nav.classList.contains('active') ? 'hidden' : 'auto';
});

// Cerrar menú al hacer clic en overlay
overlay.addEventListener('click', () => {
    hamburger.classList.remove('active');
    nav.classList.remove('active');
    overlay.classList.remove('active');
    document.body.style.overflow = 'auto';
});

// Cerrar menú al hacer clic en cualquier enlace
navLinks.forEach(link => {
    link.addEventListener('click', () => {
        hamburger.classList.remove('active');
        nav.classList.remove('active');
        overlay.classList.remove('active');
        document.body.style.overflow = 'auto';
    });
});

// Cerrar menú al presionar ESC
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && nav.classList.contains('active')) {
        hamburger.classList.remove('active');
        nav.classList.remove('active');
        overlay.classList.remove('active');
        document.body.style.overflow = 'auto';
    }
});
